diff --git a/tests/unit/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.test.ts b/tests/unit/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.test.ts
new file mode 100644
index 0000000..8a3bbe8
--- /dev/null
+++ b/tests/unit/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.test.ts
@@ -0,0 +1,107 @@
+import { describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { AgentRows, SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+const SIGNED: SignedBlock = { type: "thinking", thinking: "Let me think.", signature: "sig-1" };
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: { input_tokens: 3, output_tokens: 5, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 } };
+const TEXT_CHUNKS = 5;
+
+/** Rows that the test writes: the engine's row of a block appears only when the test calls `write`. */
+function engineRows() {
+  const signed: SignedBlock[] = [];
+  const rows: AgentRows = { read: () => signed };
+  return { rows, write: (block: SignedBlock) => { signed.push(block); } };
+}
+
+/** A step that thinks, then writes `TEXT_CHUNKS` text chunks before the engine writes the thinking block's row, as
+ *  when the engine writes it only once the response ends. `beforeStop` runs before the stop chunk.
+ *  @yields {StepEvent} The step's chunks. */
+async function* thinkThenWrite(beforeStop: () => void, stop = true): AsyncGenerator<StepEvent> {
+  yield { kind: "item", item: { kind: "thinking", index: 0, text: "Let me " } };
+  yield { kind: "item", item: { kind: "thinking", index: 0, text: "think." } };
+  for (let chunk = 0; chunk < TEXT_CHUNKS; chunk += 1) {
+    await Bun.sleep(1);
+    yield { kind: "item", item: { kind: "text", index: 1, text: `part ${chunk} ` } };
+  }
+  beforeStop();
+  if (stop) yield { kind: "item", item: STOP };
+  yield { kind: "done" };
+}
+
+async function run(events: AsyncIterable<StepEvent>, rows: AgentRows, failure = new Error("service answer")) {
+  const seen: Anthropic.RawMessageStreamEvent[] = [];
+  const answers: HostedAnswer[] = [];
+  let progress = 0;
+  let error: unknown;
+  try {
+    for await (const event of hostedStreamEvents(events, rows, 0, "claude-test", async () => failure, (answer) => answers.push(answer), () => { progress += 1; })) seen.push(event);
+  } catch (caught) {
+    error = caught;
+  }
+  return { seen, answers, progress: () => progress, error };
+}
+
+describe("hostedStreamEvents", () => {
+  test("streams a response whose thinking row arrives only after the model wrote on, in Anthropic order", async () => {
+    const engine = engineRows();
+    const result = await run(thinkThenWrite(() => { engine.write(SIGNED); }), engine.rows);
+
+    expect(result.error).toBeUndefined();
+    const signature = result.seen.findIndex((event) => event.type === "content_block_delta" && event.delta.type === "signature_delta");
+    const thinkingStop = result.seen.findIndex((event) => event.type === "content_block_stop" && event.index === 0);
+    const firstText = result.seen.findIndex((event) => "index" in event && event.index === 1);
+    expect(signature).toBeGreaterThan(-1);
+    expect(signature).toBeLessThan(thinkingStop);
+    expect(thinkingStop).toBeLessThan(firstText);
+    expect(result.seen.filter((event) => event.type === "content_block_delta" && event.delta.type === "text_delta")).toHaveLength(TEXT_CHUNKS);
+    expect(result.seen.at(-1)?.type).toBe("message_stop");
+    expect(result.answers).toEqual([{
+      message: { role: "assistant", content: [SIGNED, { type: "text", text: Array.from({ length: TEXT_CHUNKS }, (_, chunk) => `part ${chunk} `).join("") }] },
+      stopReason: "end_turn",
+    }]);
+    // Each text chunk that the stream read and held back while the row was pending counts as progress.
+    expect(result.progress()).toBe(TEXT_CHUNKS);
+  }, 2_000);
+
+  test("reports no progress while no chunk arrives", async () => {
+    const engine = engineRows();
+    const events = (async function* (): AsyncGenerator<StepEvent> {
+      yield { kind: "item", item: { kind: "thinking", index: 0, text: "Let me think." } };
+      yield { kind: "item", item: { kind: "text", index: 1, text: "held" } };
+      await Bun.sleep(200);
+      engine.write(SIGNED);
+      yield { kind: "item", item: STOP };
+      yield { kind: "done" };
+    })();
+    const result = await run(events, engine.rows);
+
+    expect(result.error).toBeUndefined();
+    expect(result.progress()).toBe(1);
+  }, 2_000);
+
+  test("fails transient when a signed row is still missing after the stop chunk", async () => {
+    const engine = engineRows();
+    const pending = run(thinkThenWrite(() => {}), engine.rows);
+    // Past the bound of the wait for the row after the stop chunk.
+    setTimeout(() => { setSystemTime(new Date(Date.now() + 120_000)); }, 100);
+    const result = await pending;
+    setSystemTime();
+
+    expect(result.error).toBeInstanceOf(LlmStreamError);
+    expect(result.error).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    expect(result.seen.some((event) => event.type === "message_stop")).toBe(false);
+    expect(result.answers).toEqual([]);
+  }, 2_000);
+
+  test("fails with the service's answer when the step ends without a stop chunk", async () => {
+    const engine = engineRows();
+    const failure = new Error("529 overloaded");
+    const result = await run(thinkThenWrite(() => {}, false), engine.rows, failure);
+
+    expect(result.error).toBe(failure);
+    expect(result.answers).toEqual([]);
+  }, 2_000);
+});

