+import type { InternalOptions, NestedTestConfig } from '../types';
+
+/**
+ * Derive the options for a value nested under `parent` at `key` or `index`.
+ * Casting and validation both use this so that descendants (for example
+ * `when()` callbacks) see the same `parent`, `index`/`key`, `value`,
+ * `originalValue`, and `path` either way.
+ *
+ * Throws a TypeError when neither `key` nor `index` is provided.
+ */
+export default function nestedOptions({
+  key,
+  index,
+  parent,
+  parentPath,
+  originalParent,
+  options,
+}: NestedTestConfig): InternalOptions & { value: any } {
+  const k = key ?? index;
+  if (k == null) {
+    throw TypeError('Must include `key` or `index` for nested validations');
+  }
+
+  const isIndex = typeof k === 'number';
+
+  return {
+    ...options,
+    parent,
+    value: parent[k],
+    originalValue: originalParent[k],
+    // FIXME: tests depend on `index` being passed around deeply,
+    //   we should not let the options.key/index bleed through
+    key: undefined,
+    // index: undefined,
+    [isIndex ? 'index' : 'key']: k,
+    path:
+      isIndex || k.includes('.')
+        ? `${parentPath || ''}[${isIndex ? k : `"${k}"`}]`
+        : (parentPath ? `${parentPath}.` : '') + key,
+  };
+}
