+import type { NestedTestConfig } from '../types';
+
+export default function nestedOptions({
+  options,
+  parent,
+  originalParent,
+  parentPath,
+  key,
+  index,
+}: NestedTestConfig) {
+  const k = key ?? index;
+  if (k == null) {
+    throw TypeError('Must include `key` or `index` for nested validations');
+  }
+
+  const isIndex = typeof k === 'number';
+  return {
+    ...options,
+    parent,
+    value: parent[k],
+    originalValue: originalParent[k],
+    // Preserve the enclosing index on object fields.
+    key: undefined,
+    [isIndex ? 'index' : 'key']: k,
+    path:
+      isIndex || k.includes('.')
+        ? `${parentPath || ''}[${isIndex ? k : `"${k}"`}]`
+        : (parentPath ? `${parentPath}.` : '') + key,
+  };
+}
