+use react::*;
+use std::cell::RefCell;
+
+#[test]
+fn input_and_compute_cells_propagate() {
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    let plus = r
+        .create_compute(&[CellId::Input(input)], |v| v[0] + 1)
+        .unwrap();
+    let times = r
+        .create_compute(&[CellId::Input(input)], |v| v[0] * 10)
+        .unwrap();
+    let sum = r
+        .create_compute(&[CellId::Compute(plus), CellId::Compute(times)], |v| {
+            v[0] + v[1]
+        })
+        .unwrap();
+    assert_eq!(r.value(CellId::Compute(sum)), Some(12));
+    assert!(r.set_value(input, 3));
+    assert_eq!(r.value(CellId::Compute(sum)), Some(34));
+}
+
+#[test]
+fn nonexistent_dependency_is_rejected() {
+    let mut r1 = Reactor::new();
+    let mut r2 = Reactor::<i32>::new();
+    let _ = r2.create_input(0);
+    let missing = r2.create_input(0);
+    let _ = r1.create_input(0);
+    assert_eq!(
+        r1.create_compute(&[CellId::Input(missing)], |_| 0),
+        Err(CellId::Input(missing))
+    );
+    assert!(!r1.set_value(missing, 1));
+}
+
+#[test]
+fn callbacks_fire_once_per_stable_change_and_can_be_removed() {
+    let calls = RefCell::new(Vec::new());
+    let other = RefCell::new(Vec::new());
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    let plus = r
+        .create_compute(&[CellId::Input(input)], |v| v[0] + 1)
+        .unwrap();
+    let minus = r
+        .create_compute(&[CellId::Input(input)], |v| v[0] - 1)
+        .unwrap();
+    let diff = r
+        .create_compute(&[CellId::Compute(plus), CellId::Compute(minus)], |v| {
+            v[0] - v[1]
+        })
+        .unwrap();
+    let constant_cb = r.add_callback(diff, |v| calls.borrow_mut().push(v)).unwrap();
+    let plus_cb = r.add_callback(plus, |v| other.borrow_mut().push(v)).unwrap();
+
+    assert!(r.set_value(input, 5));
+    assert!(calls.borrow().is_empty());
+    assert_eq!(*other.borrow(), vec![6]);
+
+    assert!(r.set_value(input, 5));
+    assert_eq!(*other.borrow(), vec![6]);
+
+    assert_eq!(r.remove_callback(plus, plus_cb), Ok(()));
+    assert_eq!(
+        r.remove_callback(plus, plus_cb),
+        Err(RemoveCallbackError::NonexistentCallback)
+    );
+    assert!(r.set_value(input, 7));
+    assert_eq!(*other.borrow(), vec![6]);
+    assert_eq!(r.remove_callback(diff, constant_cb), Ok(()));
+}

