+import { TemplateError, type TemplateToken } from "./types.js";
+
+type BlockKind = "if" | "each";
+
+export type TemplateNode =
+  | Extract<TemplateToken, { kind: "text" | "variable" }>
+  | { kind: BlockKind; path: string; position: number; children: TemplateNode[] };
+
+type BlockNode = Extract<TemplateNode, { kind: BlockKind }>;
+
+/**
+ * Builds the nested block tree from tokens. A close must match the innermost open block.
+ * Throws TemplateError at the closing tag for an unexpected or mismatched close, and at the
+ * opening tag for a block left unclosed.
+ */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const open: BlockNode[] = [];
+  for (const token of tokens) {
+    const siblings = open.at(-1)?.children ?? root;
+    if (token.kind === "open") {
+      const node: BlockNode = { kind: token.block, path: token.path, position: token.position, children: [] };
+      siblings.push(node);
+      open.push(node);
+    } else if (token.kind === "close") {
+      const innermost = open.pop();
+      if (innermost === undefined) {
+        throw new TemplateError(`Unexpected closing tag {{/${token.block}}}`, token.position);
+      }
+      if (innermost.kind !== token.block) {
+        throw new TemplateError(
+          `Mismatched closing tag {{/${token.block}}}, expected {{/${innermost.kind}}}`,
+          token.position,
+        );
+      }
+    } else {
+      siblings.push(token);
+    }
+  }
+  const unclosed = open.at(-1);
+  if (unclosed !== undefined) throw new TemplateError(`Unclosed block {{#${unclosed.kind}}}`, unclosed.position);
+  return root;
+}
