+import { afterEach, describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import type { AgentRows, SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+/** The step's events as a test sends them, one at a time. */
+function steps() {
+  const queued: StepEvent[] = [];
+  let wake: (() => void) | undefined;
+  const send = (event: StepEvent) => {
+    queued.push(event);
+    wake?.();
+  };
+  const events: AsyncIterable<StepEvent> = {
+    [Symbol.asyncIterator]: () => ({
+      next: async (): Promise<IteratorResult<StepEvent>> => {
+        while (queued.length === 0) await new Promise<void>((resolve) => { wake = resolve; });
+        const value = queued.shift();
+        if (value === undefined) throw new Error("no event");
+        return { done: false, value };
+      },
+    }),
+  };
+  return { events, item: (item: HostStepItem) => { send({ kind: "item", item }); }, done: () => { send({ kind: "done" }); } };
+}
+
+/** The engine's rows of signed blocks, which a test writes when it chooses. */
+function engineRows() {
+  const written: SignedBlock[] = [];
+  const rows: AgentRows = { read: () => written };
+  return { rows, write: (block: SignedBlock) => { written.push(block); } };
+}
+
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: { input_tokens: 3, output_tokens: 5, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 } };
+const FAILURE = new Error("529 overloaded");
+
+function run(events: AsyncIterable<StepEvent>, rows: AgentRows) {
+  const answers: HostedAnswer[] = [];
+  let progress = 0;
+  const stream = hostedStreamEvents(events, rows, 0, "claude-test", async () => FAILURE, (answer) => { answers.push(answer); }, () => { progress += 1; });
+  const seen: Anthropic.RawMessageStreamEvent[] = [];
+  const consumed = (async () => {
+    for await (const event of stream) seen.push(event);
+  })();
+  return { answers, seen, consumed, progress: () => progress };
+}
+
+/** Each event as a short label, in the order that the stream yielded them. */
+function labels(events: readonly Anthropic.RawMessageStreamEvent[]): string[] {
+  return events.map((event) => {
+    if (event.type === "content_block_start") return `start ${event.index} ${event.content_block.type}`;
+    if (event.type === "content_block_delta") return `delta ${event.index} ${event.delta.type}`;
+    if (event.type === "content_block_stop") return `stop ${event.index}`;
+    return event.type;
+  });
+}
+
+afterEach(() => { setSystemTime(); });
