+describe("hostedStreamEvents", () => {
+  test("holds the response's later blocks in order until the engine writes the row of its thinking", async () => {
+    const step = steps();
+    const engine = engineRows();
+    const stream = run(step.events, engine.rows);
+    step.item({ kind: "thinking", index: 0, text: "plan" });
+    step.item({ kind: "text", index: 1, text: "Hello" });
+    step.item({ kind: "text", index: 1, text: " world" });
+    await Bun.sleep(100);
+    // The model writes on after its thinking, and the engine has not written the thinking's row yet.
+    expect(labels(stream.seen)).toEqual(["message_start", "start 0 thinking", "delta 0 thinking_delta"]);
+    expect(stream.progress()).toBe(2);
+    step.item(STOP);
+    await Bun.sleep(100);
+    expect(stream.answers).toEqual([]);
+    engine.write({ type: "thinking", thinking: "plan more", signature: "sig" });
+    await stream.consumed;
+    expect(labels(stream.seen)).toEqual([
+      "message_start", "start 0 thinking", "delta 0 thinking_delta", "delta 0 thinking_delta", "delta 0 signature_delta", "stop 0",
+      "start 1 text", "delta 1 text_delta", "delta 1 text_delta", "stop 1", "message_delta", "message_stop",
+    ]);
+    expect(stream.seen[3]).toEqual({ type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: " more" } });
+    expect(stream.seen[4]).toEqual({ type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "sig" } });
+    expect(stream.answers).toEqual([{
+      message: { role: "assistant", content: [{ type: "thinking", thinking: "plan more", signature: "sig" }, { type: "text", text: "Hello world" }] },
+      stopReason: "end_turn",
+    }]);
+  });
