+    const step = steps();
+    const engine = engineRows();
+    const stream = run(step.events, engine.rows);
+    step.item({ kind: "text", index: 1, text: "Hi" });
+    step.item(STOP);
+    await Bun.sleep(50);
+    engine.write({ type: "redacted_thinking", data: "opaque" });
+    await stream.consumed;
+    expect(labels(stream.seen)).toEqual(["message_start", "start 0 redacted_thinking", "stop 0", "start 1 text", "delta 1 text_delta", "stop 1", "message_delta", "message_stop"]);
+    expect(stream.answers[0]?.message.content).toEqual([{ type: "redacted_thinking", data: "opaque" }, { type: "text", text: "Hi" }]);
+  });
+
+  test("fails transient when the row is still missing a minute after the stop chunk", async () => {
+    const step = steps();
+    const engine = engineRows();
+    const stream = run(step.events, engine.rows);
+    step.item({ kind: "thinking", index: 0, text: "plan" });
+    step.item(STOP);
+    await Bun.sleep(100);
+    setSystemTime(new Date(Date.now() + 61_000));
+    const error = await stream.consumed.then(() => undefined, (cause: unknown) => cause);
+    expect(error).toMatchObject({ kind: "transient" });
+    expect(String(error)).toContain("wrote no row for a signed block");
