@@ -0,0 +1,136 @@
+import { expect, spyOn, test } from "bun:test";
+import { appendFileSync } from "node:fs";
+import { join } from "node:path";
+import Anthropic from "@anthropic-ai/sdk";
+import { Redacted } from "effect";
+import { awaitWithAbortSignal } from "../../../../../../src/infra/abort.js";
+import type { ModelInfo } from "../../../../../../src/infra/llm/models.js";
+import { createAnthropicAdapter } from "../../../../../../src/orchestration/agent-runtime/llm/anthropic.js";
+import { agentRows, type SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+import { temporaryDirectories } from "../../../../../helpers/directories.js";
+
+const temporaryDirectory = temporaryDirectories();
+const thinking = { type: "thinking", thinking: "look ahead", signature: "engine-signature" } satisfies SignedBlock;
+const redacted = { type: "redacted_thinking", data: "engine-data" } satisfies SignedBlock;
+const thought = chunk({ kind: "thinking", index: 0, text: "look" });
+const stop = chunk({ kind: "stop", stopReason: "end_turn", usage: null });
+const serviceAnswer = new Error("503 Service Unavailable");
+
+function chunk(item: HostStepItem): StepEvent {
+  return { kind: "item", item };
+}
+
+function appendSigned(path: string, ...content: SignedBlock[]): void {
+  appendFileSync(path, JSON.stringify({ type: "assistant", message: { content } }) + "\n");
+}
+
+test("holds later blocks in wire order until signed rows arrive, even after a long response", async () => {
+  const path = join(temporaryDirectory("agent-stream-"), "agent.jsonl");
+  appendSigned(path, { ...thinking, signature: "earlier-step" });
+  const rows = agentRows(path, 0);
+  const from = rows.read().length;
+  const answers: HostedAnswer[] = [];
+  let progress = 0;
+  let now = 0;
+  let rowWrite: Promise<void> | undefined;
+  const clock = spyOn(Date, "now").mockImplementation(() => now);
+  try {
+    const stream = hostedStreamEvents((async function* () {
+      yield thought;
+      const elapsed = Bun.sleep(5).then(() => { now += 90_000; });
+      yield chunk({ kind: "text", index: 2, text: "Long " });
+      await elapsed;
+      yield chunk({ kind: "text", index: 2, text: "answer" });
+      rowWrite = Bun.sleep(5).then(() => { appendSigned(path, thinking, redacted); });
+      yield stop;
+    })(), rows, from, "test-model", async () => serviceAnswer, (answer) => { answers.push(answer); }, () => { progress += 1; });
+
+    const events = await Array.fromAsync(stream);
+    expect(events.slice(1, -2)).toEqual([
+      { type: "content_block_start", index: 0, content_block: { type: "thinking", thinking: "", signature: "" } },
+      { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "look" } },
+      { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: " ahead" } },
+      { type: "content_block_delta", index: 0, delta: { type: "signature_delta", signature: "engine-signature" } },
+      { type: "content_block_stop", index: 0 },
+      { type: "content_block_start", index: 1, content_block: redacted },
+      { type: "content_block_stop", index: 1 },
+      { type: "content_block_start", index: 2, content_block: { type: "text", text: "", citations: null } },
+      { type: "content_block_delta", index: 2, delta: { type: "text_delta", text: "Long " } },
+      { type: "content_block_delta", index: 2, delta: { type: "text_delta", text: "answer" } },
+      { type: "content_block_stop", index: 2 },
+    ]);
+    expect(events.at(-1)).toEqual({ type: "message_stop" });
+    expect(answers).toEqual([{ message: { role: "assistant", content: [thinking, redacted, { type: "text", text: "Long answer" }] }, stopReason: "end_turn" }]);
+    expect(progress).toBe(4);
+  } finally {
+    clock.mockRestore();
+    await rowWrite;
+  }
+});
+
+test.each([false, true])("an absent signed row preserves the service failure unless the step sent stop (%s)", async (stopped) => {
+  let now = 0;
+  const clock = spyOn(Date, "now").mockImplementation(() => {
+    now += 90_000;
+    return now;
+  });
+  try {
+    const stream = hostedStreamEvents((async function* () {
+      yield thought;
+      yield chunk({ kind: "text", index: 1, text: "Unsigned predecessor" });
+      yield stopped ? stop : { kind: "done" };
+    })(), { read: () => [] }, 0, "test-model", async () => serviceAnswer, () => {}, () => {});
+    const answer = Array.fromAsync(stream);
+    if (stopped) await expect(answer).rejects.toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    else await expect(answer).rejects.toBe(serviceAnswer);
+  } finally {
+    clock.mockRestore();
+  }
+});
+
+const model: ModelInfo = {
+  provider: "anthropic", family: "anthropic", id: "test-model", name: "Test model", reasoning: true, toolCall: true,
+  attachment: true, temperature: true, openWeights: false, cost: { input: 0, output: 0 }, pricing: { status: "unavailable", reason: "missing-rate-card" },
+  modalities: { input: ["text"], output: ["text"] }, contextLimit: 100_000, outputLimit: 8_000,
+};
+
+test.each([true, false])("the adapter distinguishes incoming chunks from silence with a row pending (%s)", async (sending) => {
+  const previous = process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+  process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = "120";
+  try {
+    const adapter = await createAnthropicAdapter(Redacted.make("fixture"), model.id, model, {
+      operations: {
+        async createStream(_params, { onProgress, signal }) {
+          const controller = new AbortController();
+          const requestSignal = AbortSignal.any([signal, controller.signal]);
+          let signed = false;
+          const events = (async function* (): AsyncGenerator<StepEvent> {
+            yield thought;
+            yield chunk({ kind: "text", index: 1, text: "answer" });
+            if (!sending) await awaitWithAbortSignal(new Promise<never>(() => {}), requestSignal);
+            for (let index = 0; index < 6; index += 1) {
+              await awaitWithAbortSignal(Bun.sleep(30), requestSignal);
+              yield chunk({ kind: "text", index: 1, text: "." });
+            }
+            signed = true;
+            yield stop;
+          })();
+          const stream = hostedStreamEvents(events, { read: () => {
+            requestSignal.throwIfAborted();
+            return signed ? [thinking] : [];
+          } }, 0, model.id, async () => serviceAnswer, () => {}, () => { onProgress?.(); });
+          return { data: Object.assign(stream, { controller }), response: new Response(null) };
+        },
+        isBadRequestError: (error) => error instanceof Anthropic.BadRequestError,
+      },
+    });
+    const result = Array.fromAsync(adapter.streamWithTools({ messages: [{ kind: "user", origin: "human", content: "Answer." }], systemPrompt: { stable: "", session: "", conversation: "" }, tools: [], reasoningEffort: "medium" }));
+    if (sending) expect((await result).at(-1)).toMatchObject({ kind: "done", stopReason: "end_turn" });
+    else await expect(result).rejects.toThrow("thinking block stalled");
+  } finally {
+    if (previous === undefined) delete process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS;
+    else process.env.FLYWHEEL_STREAM_THINKING_STALL_TIMEOUT_MS = previous;
+  }
+});

