@@ -0,0 +1,17 @@
+import type { Rollup } from "./types.js";
+
+/** In-memory rollup storage keyed by metric name; the shared source for collectors and reports. */
+export class MetricsStore {
+  readonly #rollupsByMetric = new Map<string, Rollup[]>();
+
+  append(rollup: Rollup): void {
+    const rollups = this.#rollupsByMetric.get(rollup.metric);
+    if (rollups) rollups.push(rollup);
+    else this.#rollupsByMetric.set(rollup.metric, [rollup]);
+  }
+
+  /** Returns the rollups stored for `metric` in insertion order, or an empty collection for an unknown metric. */
+  read(metric: string): readonly Rollup[] {
+    return this.#rollupsByMetric.get(metric) ?? [];
+  }
+}

