+use react::*;
+use std::cell::RefCell;
+
+#[test]
+fn compute_cells_update_and_reject_missing_dependencies() {
+    let mut other = Reactor::new();
+    let foreign = other.create_input(1);
+    let mut r = Reactor::new();
+    let a = r.create_input(1);
+    let _ = r.create_input(0);
+    let b = r
+        .create_compute(&[CellId::Input(a)], |v| v[0] + 1)
+        .unwrap();
+    let c = r
+        .create_compute(&[CellId::Input(a), CellId::Compute(b)], |v| v[0] * v[1])
+        .unwrap();
+    assert_eq!(r.value(CellId::Compute(c)), Some(2));
+    assert!(r.set_value(a, 3));
+    assert_eq!(r.value(CellId::Compute(c)), Some(12));
+    let _ = foreign;
+    let mut lone = Reactor::<i32>::new();
+    assert!(!lone.set_value(a, 1));
+    assert_eq!(lone.value(CellId::Input(a)), None);
+    assert_eq!(
+        lone.create_compute(&[CellId::Input(a)], |v| v[0]),
+        Err(CellId::Input(a))
+    );
+}
+
+#[test]
+fn callbacks_fire_once_only_on_stable_change() {
+    let calls = RefCell::new(Vec::new());
+    let removed = RefCell::new(Vec::new());
+    let mut r = Reactor::new();
+    let a = r.create_input(1);
+    let plus = r.create_compute(&[CellId::Input(a)], |v| v[0] + 1).unwrap();
+    let minus = r.create_compute(&[CellId::Input(a)], |v| v[0] - 1).unwrap();
+    let neg = r.create_compute(&[CellId::Compute(minus)], |v| -v[0]).unwrap();
+    // Always 2 regardless of a: callbacks must not fire.
+    let sum = r
+        .create_compute(&[CellId::Compute(plus), CellId::Compute(neg)], |v| v[0] + v[1])
+        .unwrap();
+    r.add_callback(plus, |v| calls.borrow_mut().push(v)).unwrap();
+    r.add_callback(sum, |v| calls.borrow_mut().push(v * 100)).unwrap();
+    let cb = r.add_callback(minus, |v| removed.borrow_mut().push(v)).unwrap();
+    r.set_value(a, 1);
+    assert!(calls.borrow().is_empty());
+    r.set_value(a, 5);
+    assert_eq!(*calls.borrow(), vec![6]);
+    assert_eq!(*removed.borrow(), vec![4]);
+    assert_eq!(r.remove_callback(minus, cb), Ok(()));
+    assert_eq!(
+        r.remove_callback(minus, cb),
+        Err(RemoveCallbackError::NonexistentCallback)
+    );
+    r.set_value(a, 7);
+    assert_eq!(*removed.borrow(), vec![4]);
+    let other = Reactor::<i32>::new();
+    let mut other = other;
+    assert_eq!(
+        other.remove_callback(minus, cb),
+        Err(RemoveCallbackError::NonexistentCell)
+    );
+    assert_eq!(other.add_callback(minus, |_| ()), None);
+}

