+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string }
+  | { kind: "variable"; path: string; escaped: boolean }
+  | { kind: "if" | "each"; path: string; body: TemplateNode[] };
+
+/**
+ * Builds the nested block tree from tokens, matching each close with the innermost open block.
+ * Throws TemplateError at the closing offset for an unexpected or mismatched close, and at the opening offset for an unclosed block.
+ */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const open: { token: Extract<TemplateToken, { kind: "open" }>; body: TemplateNode[] }[] = [];
+  let body = root;
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "text":
+        body.push({ kind: "text", value: token.value });
+        break;
+      case "variable":
+        body.push({ kind: "variable", path: token.path, escaped: token.escaped });
+        break;
+      case "open": {
+        const block: TemplateNode = { kind: token.block, path: token.path, body: [] };
+        body.push(block);
+        open.push({ token, body });
+        body = block.body;
+        break;
+      }
+      case "close": {
+        const innermost = open.pop();
+        if (!innermost) throw new TemplateError(`Unexpected closing tag {{/${token.block}}}`, token.position);
+        if (innermost.token.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing tag {{/${token.block}}}, expected {{/${innermost.token.block}}}`,
+            token.position,
+          );
+        }
+        body = innermost.body;
+        break;
+      }
+    }
+  }
+  const unclosed = open.at(-1);
+  if (unclosed) throw new TemplateError(`Unclosed block {{#${unclosed.token.block}}}`, unclosed.token.position);
+  return root;
+}
