+/**
+ * Renders a template against a context. `{{path}}` is HTML-escaped, `{{{path}}}` is raw, `{{#if path}}` uses JavaScript truthiness,
+ * and `{{#each path}}` repeats its body for each array item with that item as the context. Missing and nullish values render as empty text.
+ * Throws TemplateError for malformed tags and unbalanced blocks.
+ */
+export function render(template: string, context: TemplateContext = {}): string {
+  return renderNodes(parse(tokenize(template)), context);
+}
+
+function renderNodes(nodes: readonly TemplateNode[], context: unknown): string {
+  return nodes.map((node) => renderNode(node, context)).join("");
+}
+
+function renderNode(node: TemplateNode, context: unknown): string {
+  switch (node.kind) {
+    case "text":
+      return node.value;
+    case "variable": {
+      const value = resolve(context, node.path);
+      const text = value === null || value === undefined ? "" : String(value);
+      return node.escaped ? escapeHtml(text) : text;
+    }
+    case "if":
+      return resolve(context, node.path) ? renderNodes(node.body, context) : "";
+    case "each": {
+      const items = resolve(context, node.path);
+      return Array.isArray(items) ? items.map((item) => renderNodes(node.body, item)).join("") : "";
+    }
+  }
+}
+
+function resolve(context: unknown, path: string): unknown {
+  let value = context;
+  for (const segment of path.split(".")) {
+    if (value === null || value === undefined) return undefined;
+    value = (value as Record<string, unknown>)[segment];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
 }
