+import { TemplateError, type TemplateToken } from "./types.js";
+
+type BlockNode = Extract<TemplateToken, { kind: "open" }> & { children: TemplateNode[] };
+export type TemplateNode = Extract<TemplateToken, { kind: "text" | "variable" }> | BlockNode;
+
+/** Build a nested tree or throw TemplateError at the offending token. */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: BlockNode[] = [];
+
+  for (const token of tokens) {
+    const parent = stack[stack.length - 1];
+    const children = parent?.children ?? root;
+
+    switch (token.kind) {
+      case "text":
+      case "variable":
+        children.push(token);
+        break;
+      case "open": {
+        const block: BlockNode = { ...token, children: [] };
+        children.push(block);
+        stack.push(block);
+        break;
+      }
+      case "close":
+        if (!parent) {
+          throw new TemplateError(`Unexpected closing tag /${token.block}`, token.position);
+        }
+        if (parent.block !== token.block) {
+          throw new TemplateError(`Mismatched closing tag /${token.block}, expected /${parent.block}`, token.position);
+        }
+        stack.pop();
+        break;
+    }
+  }
+
+  const unclosed = stack.pop();
+  if (unclosed) {
+    throw new TemplateError(`Unclosed block #${unclosed.block}`, unclosed.position);
+  }
+  return root;
+}
