+function resolvePath(scope: unknown, path: string): unknown {
+  for (const segment of path.split(".")) {
+    scope = (scope as Readonly<Record<string, unknown>> | null | undefined)?.[segment];
+  }
+  return scope;
+}
+
+function escapeHtml(value: string): string {
+  return value
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function* scopedNodes(nodes: readonly TemplateNode[], scopes: Iterable<unknown>) {
+  for (const scope of scopes) {
+    for (const node of nodes) {
+      yield { node, scope };
+    }
+  }
+}
+
+/** Render with the given context. Invalid block structure throws TemplateError before any values are read. */
+export function render(template: string, context: TemplateContext = {}): string {
+  const output: string[] = [];
+  const stack = [scopedNodes(parse(tokenize(template)), [context])];
+
+  while (stack.length > 0) {
+    const step = stack[stack.length - 1].next();
+    if (step.done) {
+      stack.pop();
+      continue;
+    }
+
+    const { node, scope } = step.value;
+    if (node.kind === "text") {
+      output.push(node.value);
+      continue;
+    }
+
+    const value = resolvePath(scope, node.path);
+    if (node.kind === "variable") {
+      const text = String(value ?? "");
+      output.push(node.escaped ? escapeHtml(text) : text);
+    } else if (node.block === "if") {
+      if (value) stack.push(scopedNodes(node.children, [scope]));
+    } else if (Array.isArray(value)) {
+      stack.push(scopedNodes(node.children, value));
+    }
+  }
+
+  return output.join("");
 }
