+function tagToken(body: string, escaped: boolean, position: number): TemplateToken | undefined {
+  const path = body.trim();
+  if (!path) return;
+
+  if (escaped && (path.startsWith("#") || path.startsWith("/"))) {
+    const [, marker, block, blockPath] = /^([#/])(\S+)(?:\s+([\s\S]+))?$/.exec(path) ?? [];
+    if (block !== "if" && block !== "each") return;
+
+    if (marker === "#" && blockPath !== undefined) {
+      return { kind: "open", block, path: blockPath, position };
+    }
+    if (marker === "/" && blockPath === undefined) {
+      return { kind: "close", block, position };
+    }
+    return;
+  }
+
+  return { kind: "variable", path, escaped, position };
+}
