-    : [{ kind: "text", value: template, position: 0 }];
+  const tokens: TemplateToken[] = [];
+  let textStart = 0;
+
+  // Do not read the last two braces of an incomplete raw opener as a new tag.
+  for (const match of template.matchAll(/(?<!\{)(?:\{\{\{([^{}]*)\}\}\}|\{\{([^{}]*)\}\})/g)) {
+    const token = tagToken(match[1] ?? match[2], match[1] === undefined, match.index);
+    if (!token) continue;
+
+    if (textStart < match.index) {
+      tokens.push({ kind: "text", value: template.slice(textStart, match.index), position: textStart });
+    }
+    tokens.push(token);
+    textStart = match.index + match[0].length;
+  }
+
+  if (textStart < template.length) {
+    tokens.push({ kind: "text", value: template.slice(textStart), position: textStart });
+  }
+  return tokens;
